function fifoSourceInfo(f){const src=events.find(x=>x.id===f.source),linked=f.sourcePurchaseId?events.find(x=>x.id===f.sourcePurchaseId):null,base=linked||src;let type=f.sourceType||src?.type||'';if(type==='purchase'){const d=base?.data||{},supplier=calc.contacts[d.partyId]?.name||'Tanpa supplier';return {label:`Kulak · ${supplier}`,meta:`${displayDateTime(base)} · ${rupiah(d.price||f.unit||0)}/kg`,eventId:base?.id||'',kind:'purchase'}}if(type==='adjust'||src?.type==='adjust'){const d=src?.data||{},purchase=linked||stockAdjustPurchaseRef(src),supplier=purchase?calc.contacts[purchase.data?.partyId]?.name||'Tanpa supplier':'—';return {label:`Stok opname${purchase?' · sisa '+supplier:''}`,meta:`${displayDateTime(src)} · Modal ${rupiah(f.unit||d.price||0)}/kg`,eventId:src?.id||'',kind:'adjust'}}if(type==='initial'||src?.type==='initial')return {label:'Stok awal',meta:`${displayDateTime(src)} · Modal ${rupiah(f.unit||0)}/kg`,eventId:src?.id||'',kind:'initial'};if(type==='settlement'||src?.type==='settlement')return {label:'Penggantian telur',meta:`${displayDateTime(src)} · Modal ${rupiah(f.unit||0)}/kg`,eventId:src?.id||'',kind:'settlement'};return {label:'Sumber stok',meta:`${displayDateTime(src)} · Modal ${rupiah(f.unit||0)}/kg`,eventId:src?.id||'',kind:type||'unknown'}}
function stockAdjustSoldInfo(e){const s=stockAdjustSnapshot(e);if(!s||s.delta<=0)return {soldQty:0,revenue:0,cogs:0,profit:0,remaining:0,sales:[]};let soldQty=0,revenue=0;const sales=[];for(const sale of activeEvents().filter(x=>x.type==='sale'&&eventBefore(e,x)).sort(compareEvents)){const o=calc.outcomes[sale.id]||{},items=Array.isArray(o.itemBreakdown)?o.itemBreakdown:[],totalSaleWeight=items.reduce((n,it)=>n+(Number(it.weight)||0),0)||1;let usedFromThis=0,saleRevenue=0,itemTotal=0;const breakdown=[];for(const it of items){if(it.productId!==e.data.productId)continue;itemTotal+=Number(it.weight)||0;for(const f of (Array.isArray(it.fifo)?it.fifo:[])){const qty=Number(f.qty)||0,info=fifoSourceInfo(f);breakdown.push({qty,unit:Number(f.unit)||0,...info,fromThis:f.source===e.id});if(f.source===e.id){usedFromThis+=qty;if(sale.data?.channel==='shopee')saleRevenue+=Math.round((Number(o.revenue)||0)*qty/totalSaleWeight);else saleRevenue+=Math.round(qty*(Number(it.price)||0)/1000)}}}soldQty+=usedFromThis;revenue+=saleRevenue;if(usedFromThis)sales.push({id:sale.id,date:displayDateTime(sale),qty:usedFromThis,totalQty:itemTotal,revenue:saleRevenue,breakdown})}const capped=Math.min(Math.max(0,soldQty),s.delta),cogs=s.delta>0?Math.round(s.value*capped/s.delta):0;let running=s.delta;for(const row of sales){running=Math.max(0,running-row.qty);row.remainingAfter=running}return {soldQty:capped,revenue,cogs,profit:revenue-cogs,remaining:Math.max(0,s.delta-capped),sales}}
function sharedEventMeta(e){const d=e.data||{},o=calc.outcomes[e.id]||{};if(e.type==='adjust'&&d.productId){const s=stockAdjustSnapshot(e);if(!s)return `Stok fisik ${fmt(d.actual||0)} gram · Dampak HPP ${rupiah(o.cogs||0)}`;const arah=s.delta>0?'Tambah':s.delta<0?'Kurang':'Tetap',sold=s.delta>0?stockAdjustSoldInfo(e):null;return `Stok fisik ${fmt(s.actual)} gram · ${arah} ${s.delta>0?'+':''}${fmt(s.delta)} gram · Nilai penyesuaian ${rupiah(s.value)}${sold?` · Terjual ${fmt(sold.soldQty)} gram = ${rupiah(sold.revenue)}`:''}`}if(e.type==='adjust')return `Tray layak ${fmt(d.trayAvailable||0)} pcs · rusak ${fmt(d.trayBroken||0)} pcs`;if(e.type==='expense')return `${d.name||'Biaya'} · ${rupiah(d.amount||o.cost||0)}`;if(e.type==='return')return `${fmt(d.weight||0)} gram · ${d.direction==='supplier'?'Ke supplier':d.direction==='customer'?'Dari customer':'Busuk di gudang'}`;return `${kindNames[e.type]||e.type} · HPP ${rupiah(o.cogs||0)} · Biaya ${rupiah(o.cost||0)}`}
