function auditPurchaseLabel(id){const e=events.find(x=>x.id===id),d=e?.data||{};return e?`${auditProductName(d.productId)} · ${auditPartyName(d.partyId)} · ${displayDateTime(e)} · ${fmt(d.weight||0)} g`:'Transaksi kulak tidak ditemukan'}
function auditSnapshotSummary(snap){if(!snap)return '—';const d=snap.data||{},type=snap.type||'',date=`${snap.date||''}${d.time?' '+d.time:''}`.trim();if(type==='sale'){const items=saleItemsOf(d).filter(x=>x.productId);const itemText=items.map(x=>`${auditProductName(x.productId)} ${fmt(x.weight||0)} g`).join(' + ')||'Penjualan';return `${date} · ${d.channel==='shopee'?'Shopee':auditPartyName(d.partyId)} · ${itemText}`};if(type==='purchase')return `${date} · ${auditPartyName(d.partyId)} · ${auditProductName(d.productId)} ${fmt(d.weight||0)} g`;if(type==='adjust')return `${date} · ${d.productId?auditProductName(d.productId)+' stok '+fmt(d.actual||0)+' g':'Stok tray'}`;if(type==='expense')return `${date} · ${d.name||'Biaya'} · ${rupiah(d.amount||0)}`;if(type==='contact'||type==='contactUpdate')return `${date} · ${d.name||'Customer / supplier'}`;if(type==='product'||type==='productUpdate')return `${date} · ${d.name||auditProductName(d.target)}`;return `${date} · ${kindNames[type]||type}`}
function auditDiffRows(before,after){const br=auditSnapshotRows(before),ar=auditSnapshotRows(after),bm=new Map(br),am=new Map(ar),keys=[...new Set([...bm.keys(),...am.keys()])];return keys.filter(k=>String(bm.get(k)??'')!==String(am.get(k)??'')).map(k=>[k,bm.get(k)??'—',am.get(k)??'—'])}
function auditDetail(id){const a=logCache.find(x=>x.id===id);if(!a)return;const before=a.before,after=a.after,d=after||before||{},when=a.at?new Date(a.at).toLocaleString('id-ID'):'—',actionLabel={add:'Tambah data',edit:'Edit data',delete:'Batalkan / hapus data'},summary=auditSnapshotSummary(after||before),head=[['Waktu log',when],['Aksi',actionLabel[a.action]||a.action||'Aktivitas'],['Kategori',kindNames[d.type]||d.type||'—'],['Transaksi',summary],...(a.reason?[['Alasan',a.reason]]:[])];let body=detailGrid(head);
 if(a.action==='edit'&&before&&after){const diffs=auditDiffRows(before,after);body+=`<h3>Perubahan yang dilakukan</h3>${diffs.length?`<div class="audit-change-list">${diffs.map(([k,bv,av])=>`<div class="audit-change-row"><b>${esc(k)}</b><div><span>Sebelum</span><strong>${esc(bv)}</strong></div><div><span>Sesudah</span><strong>${esc(av)}</strong></div></div>`).join('')}</div>`:'<p class="empty">Tidak ada perubahan nilai yang terdeteksi.</p>'}`}
 else {const snap=after||before;body+=`<h3>${a.action==='delete'?'Data yang dibatalkan':'Rincian data'}</h3>${detailGrid(auditSnapshotRows(snap))}`}
 if(a.target&&events.some(e=>e.id===a.target&&!e.voided))body+=`<div class="form-actions"><button class="outline" data-detail="${esc(a.target)}">Buka detail transaksi</button></div>`;modal('Detail Log Aktivitas',body);rebindModalContent()}
function rebindModalContent(){decorateIcons();const logSize=$('modalBody').querySelector('#logPageSize');if(logSize)logSize.onchange=e=>{logPageSize=Number(e.target.value)||10;logPage=1;renderActivityLog()};const notaSize=$('modalBody').querySelector('#notaPageSize');if(notaSize)notaSize.onchange=e=>{notaPageSize=Number(e.target.value)||10;notaPage=1;renderCustomerDetail(currentCustomerDetailId,false)}}
function manage(restore=false){manageEditing=false;formDirty=false;(restore?replaceModal:modal)('Kelola Data · Edit & Hapus',`<p class="hint">Khusus memperbaiki input salah. Setelah Simpan atau Close dari form Edit, Anda kembali ke daftar ini.</p><div class="form-grid">${choose('Kategori','manageType',[['all','Semua'],...Object.entries(kindNames).map(([k,v])=>[k,v])],restore?manageState.type:'all')}${field('Cari nama / tanggal / nomor','manageSearch',restore?manageState.term:'',{type:'text'})}</div><div id="manageResults"></div>`);const typeEl=$('modalBody').querySelector('[name=manageType]'),searchEl=$('modalBody').querySelector('[name=manageSearch]');const draw=()=>{manageState.type=typeEl.value;manageState.term=searchEl.value;const type=manageState.type,term=manageState.term.toLowerCase(),rows=activeEvents().filter(e=>(type==='all'||e.type===type)&&[e.id,e.date,e.data?.time,e.data?.name,e.data?.note,e.data?.productId,JSON.stringify(e.data?.items||[]),kindNames[e.type],calc.contacts[e.data?.partyId]?.name].some(s=>String(s||'').toLowerCase().includes(term)));$('manageResults').innerHTML=historyRows(rows,true);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{manageState.scroll=$('modal').querySelector('.modal-card')?.scrollTop||0;manageEditing=true;formDirty=false;sectionAction('edit',events.find(e=>e.id===b.dataset.edit).type,b.dataset.edit)});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteForm(b.dataset.delete))};typeEl.onchange=draw;searchEl.oninput=draw;draw();if(restore)setTimeout(()=>{const c=$('modal').querySelector('.modal-card');if(c)c.scrollTop=manageState.scroll||0},0)}
async function saveProductPrices(form){if(busy)return;try{const changes=products().map(p=>({p,value:integer(form.elements.namedItem('price_'+p.id).value||'0','Harga '+p.name)})).filter(x=>x.value!==(x.p.salePrice||0));if(!changes.length){show('Tidak ada perubahan harga.');close();return}busy=true;const snap=await getDocsFromServer(collection(db,'users',uid,'events')),current=normalized(snap),maxSeq=Math.max(0,...current.map(e=>e.seq||0));await runTransaction(db,async tx=>{const guard=await tx.get(revisionRef()),revision=guard.exists()?guard.data().value||0:0;required(revision===current.length,'Data berubah di perangkat lain. Ulangi simpan harga.');changes.forEach((x,i)=>{const id=newId(),date=today(),time=nowTime(),data={target:x.p.id,name:x.p.name,active:x.p.active!==false,salePrice:x.value,time},after={type:'productUpdate',date,data};tx.set(eventRef(id),{id,type:'productUpdate',date,seq:maxSeq+i+1,voided:false,label:kindNames.productUpdate,data});tx.set(doc(collection(db,'users',uid,'audit')),{target:id,action:'add',reason:'Perubahan harga jual default',before:null,after,at:new Date().toISOString()})});tx.set(revisionRef(),{value:revision+changes.length,updatedAt:new Date().toISOString()})});close();show('Harga jual default tersimpan.')}catch(e){show(e.message,true)}finally{busy=false}}
function priceSettings(){modal('Pengaturan Harga Produk',`<form id="priceSettingsForm"><div class="form-grid">${products().map(p=>field('Harga '+p.name+' / kg (Rp)','price_'+p.id,fmt(p.salePrice||0),{required:true,placeholder:'0'})).join('')}</div><p class="hint">Harga ini otomatis dipakai transaksi Offline/Online. Harga khusus tetap dapat diubah per item saat checkbox Harga khusus aktif.</p><div class="form-actions"><button class="primary" type="submit">Simpan Harga</button></div></form>`);const f=$('priceSettingsForm');f.addEventListener('focusin',e=>{const el=e.target;if(el instanceof HTMLInputElement&&el.inputMode==='numeric'&&integer(el.value||'0')===0)el.value=''});f.onsubmit=e=>{e.preventDefault();saveProductPrices(f)}}
function debtDetail(id){const i=calc.invoices[id],c=i&&calc.contacts[i.partyId];if(!i||i.debt<=0)return;const sourceEvent=events.find(e=>e.id===id),payments=activeEvents().filter(e=>e.type==='settlement'&&e.data?.mode==='debt'&&e.data?.invoiceId===id);modal('Bon Aktif · '+(c?.name||'Customer'),`<div class="detail-grid"><div class="detail-item"><span>Tanggal & waktu</span><b>${esc(sourceEvent?displayDateTime(sourceEvent):i.date)}</b></div><div class="detail-item"><span>Total tagihan</span><b>${rupiah(i.revenue||0)}</b></div><div class="detail-item"><span>Sudah dibayar</span><b>${rupiah(i.paid||0)}</b></div><div class="detail-item"><span>Sisa bon</span><b>${rupiah(i.debt||0)}</b></div></div><h3>Riwayat cicilan</h3>${payments.map(e=>`<div class="row debt-payment-row"><span>${esc(displayDateTime(e))}</span><b>${rupiah(e.data?.amount||0)}</b></div>`).join('')||'<p class="empty">Belum ada cicilan setelah transaksi awal.</p>'}<div class="form-actions"><button class="secondary" id="debtInstallment">Bayar cicilan</button><button class="primary" id="debtFull">Lunasi</button></div>`);const openPay=full=>{sectionAction('add','settlement');const f=$('editForm');f.elements.namedItem('partyId').value=i.partyId;f.elements.namedItem('partyId').dispatchEvent(new Event('change'));f.elements.namedItem('invoiceId').value=id;f.elements.namedItem('mode').value='debt';f.elements.namedItem('amount').value=fmt(full?i.debt:0)};$('debtInstallment').onclick=()=>openPay(false);$('debtFull').onclick=()=>openPay(true)}

